INSERT INTO glossario_catalogo (id, revisado_em) VALUES (1, '2026-11-08');
INSERT INTO glossario_fontes (id, nome, url) VALUES ('cpc', 'Código de Processo Civil · Planalto', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm');
INSERT INTO glossario_fontes (id, nome, url) VALUES ('cf', 'Constituição Federal · Planalto', 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm');
INSERT INTO glossario_fontes (id, nome, url) VALUES ('arbitragem', 'Lei de Arbitragem · Planalto', 'https://www.planalto.gov.br/ccivil_03/leis/l9307.htm');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('acao-judicial', 'Ação judicial', 'Processo civil', 'Meio de pedir ao Poder Judiciário a proteção de um direito. O pedido pode buscar, por exemplo, uma declaração, uma obrigação ou uma reparação.', 'Uma pessoa procura a Justiça para cobrar uma dívida que não foi paga.', 'Arts. 2º, 3º e 19', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('acordao', 'Acórdão', 'Processo civil', 'Decisão tomada em conjunto por um órgão de um tribunal. Ela registra o resultado do julgamento realizado por vários julgadores.', 'Uma turma do tribunal analisa um recurso e publica um acórdão com sua decisão.', 'Art. 204', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('autor', 'Autor', 'Processo civil', 'Parte que apresenta um pedido ao Judiciário e inicia a ação. Pode ser uma pessoa, uma empresa ou outra entidade com capacidade de participar do processo.', 'Na ação de cobrança proposta por Ana, ela ocupa a posição de autora.', 'Arts. 2º e 319, II', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('citacao', 'Citação', 'Processo civil', 'Ato que chama formalmente o réu, o executado ou outro interessado para participar do processo. Não significa que essa pessoa já tenha sido condenada.', 'A empresa recebe uma citação para participar de uma ação e apresentar sua defesa.', 'Art. 238', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('coisa-julgada', 'Coisa julgada', 'Processo civil', 'A coisa julgada material dá estabilidade à decisão sobre o pedido quando ela não admite mais recurso. Em regra, impede discutir novamente o que foi decidido, nos limites fixados pela lei.', 'Uma decisão definitiva sobre a cobrança não pode ser simplesmente rediscutida em outra ação igual.', 'Arts. 502 e 503', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('conciliacao', 'Conciliação', 'Processo civil', 'Tentativa de resolver um conflito por acordo, com ajuda de um conciliador. Ele pode sugerir soluções, mas não pode obrigar as partes a aceitá-las.', 'Consumidor e empresa negociam um acordo de reembolso com auxílio do conciliador.', 'Art. 165, § 2º', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('contestacao', 'Contestação', 'Processo civil', 'Resposta em que o réu apresenta sua defesa contra o pedido do autor, com os argumentos e as provas que pretende utilizar.', 'Em uma cobrança, o réu apresenta contestação e informa que já pagou o valor.', 'Art. 336', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('contraditorio', 'Contraditório', 'Processo civil', 'Garantia de conhecer o que é apresentado no processo e poder se manifestar, influenciando a decisão. A lei prevê situações específicas em que a manifestação ocorre depois de uma medida urgente.', 'Após a apresentação de um documento relevante, a outra parte tem oportunidade de comentá-lo.', 'Arts. 7º, 9º e 10', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('decisao-interlocutoria', 'Decisão interlocutória', 'Processo civil', 'Decisão do juiz que resolve uma questão do processo sem se enquadrar como sentença. Pode tratar, por exemplo, de uma medida provisória enquanto o caso continua.', 'O juiz decide um pedido de tutela de urgência antes de concluir o julgamento da ação.', 'Art. 203, § 2º', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('despacho', 'Despacho', 'Processo civil', 'Pronunciamento do juiz que dá andamento ao processo sem resolver uma questão por decisão. É diferente de sentença e de decisão interlocutória.', 'O juiz determina que uma parte seja ouvida sobre um documento juntado ao processo.', 'Art. 203, § 3º', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('habeas-corpus', 'Habeas corpus', 'Constitucional', 'Instrumento para proteger a liberdade de locomoção quando ela sofre, ou está ameaçada de sofrer, uma restrição ilegal ou decorrente de abuso de poder.', 'Um pedido de habeas corpus pode questionar a legalidade de uma prisão.', 'Art. 5º, LXVIII', 'cf');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('intimacao', 'Intimação', 'Processo civil', 'Comunicação formal que informa alguém sobre um ato ou acontecimento do processo. Pode dar ciência de uma decisão ou da necessidade de praticar algum ato.', 'A advogada é intimada de uma decisão publicada no processo.', 'Art. 269', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('jurisprudencia', 'Jurisprudência', 'Processo civil', 'Conjunto de decisões que mostra como os tribunais interpretam e aplicam o Direito. Ajuda a conhecer o entendimento adotado em questões semelhantes.', 'Uma estudante consulta decisões de um tribunal para entender como ele julga determinado assunto.', 'Arts. 926 e 927', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('mandado-de-seguranca', 'Mandado de segurança', 'Constitucional', 'Instrumento para proteger um direito demonstrável de imediato, chamado líquido e certo, contra ilegalidade ou abuso de poder de autoridade pública ou de quem exerce função pública, quando não cabem habeas corpus ou habeas data.', 'Uma negativa ilegal de autoridade pode ser questionada por esse meio se os requisitos forem atendidos.', 'Art. 5º, LXIX', 'cf');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('mediacao', 'Mediação', 'Processo civil', 'Forma de resolver conflitos com ajuda de um mediador, que facilita o diálogo para que as próprias partes construam uma solução. É especialmente útil quando existe uma relação anterior entre elas.', 'Vizinhos participam de mediação para conversar sobre um conflito e tentar chegar a um acordo.', 'Art. 165, § 3º', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('onus-da-prova', 'Ônus da prova', 'Processo civil', 'Distribuição do encargo de demonstrar os fatos alegados no processo. A regra geral atribui tarefas ao autor e ao réu, mas a lei e as particularidades do caso podem modificar essa distribuição.', 'Em uma cobrança, o autor demonstra a dívida; se o réu afirma que pagou, em regra deve provar o pagamento.', 'Art. 373', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('peticao-inicial', 'Petição inicial', 'Processo civil', 'Documento que apresenta o pedido do autor ao Judiciário. Identifica as partes e explica os fatos, os fundamentos e o que se pretende obter com a ação.', 'Na petição inicial, a autora relata a dívida e pede a condenação ao pagamento.', 'Art. 319', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('prova', 'Prova', 'Processo civil', 'Elemento usado para demonstrar os fatos relevantes de um processo e ajudar o juiz a decidir. Documentos, depoimentos e perícias são exemplos de meios de prova.', 'Um comprovante bancário pode servir como prova de um pagamento.', 'Art. 369', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('recurso', 'Recurso', 'Processo civil', 'Meio previsto em lei para pedir o reexame de uma decisão dentro do processo. Cada modalidade tem finalidade, requisitos e prazo próprios.', 'A parte apresenta uma apelação para pedir ao tribunal que examine uma sentença.', 'Arts. 994 e 1.009', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('reu', 'Réu', 'Processo civil', 'Parte contra a qual o autor formula um pedido. O réu pode se defender; ocupar essa posição não significa, por si só, ter cometido uma irregularidade.', 'Na ação em que Ana cobra uma empresa, a empresa é a ré.', 'Arts. 319, II, e 336', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('segredo-de-justica', 'Segredo de justiça', 'Processo civil', 'Restrição à publicidade de um processo nas hipóteses previstas em lei, como para proteger a intimidade. O acesso aos autos fica limitado conforme as regras aplicáveis.', 'Um processo sobre guarda de filhos pode tramitar em segredo de justiça.', 'Art. 189', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('sentenca', 'Sentença', 'Processo civil', 'No procedimento comum civil, é a decisão que encerra a fase de análise e julgamento do caso ou extingue a execução, ressalvadas as regras especiais. Pode resolver o pedido ou encerrar essa fase sem analisá-lo.', 'O juiz profere sentença acolhendo ou rejeitando o pedido de cobrança. Ainda pode haver recurso.', 'Art. 203, § 1º, e arts. 485 e 487', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('sumula', 'Súmula', 'Processo civil', 'Enunciado que resume um entendimento dominante de um tribunal sobre uma questão jurídica. Nem toda súmula é vinculante; os efeitos dependem da modalidade e das regras aplicáveis.', 'Ao estudar um tema, a turma consulta a súmula que sintetiza o entendimento do tribunal.', 'Arts. 926, § 1º, e 927', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('transito-em-julgado', 'Trânsito em julgado', 'Processo civil', 'Momento em que uma decisão deixa de admitir recurso. Não se confunde com a simples publicação da sentença, que ainda pode ser questionada por recurso.', 'Encerradas as possibilidades de recurso, registra-se o trânsito em julgado da decisão.', 'Arts. 502 e 507', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('tutela-de-urgencia', 'Tutela de urgência', 'Processo civil', 'Medida provisória para proteger um direito quando há elementos que indicam sua provável existência e risco de dano ou de perda da utilidade do processo. Depende da avaliação dos requisitos legais pelo juiz.', 'Uma parte pede uma providência imediata para evitar um prejuízo enquanto o processo continua.', 'Art. 300', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('agravo-de-instrumento', 'Agravo de instrumento', 'Processo civil', 'Recurso usado para pedir ao tribunal a revisão de determinadas decisões tomadas pelo juiz durante o processo, nas hipóteses previstas em lei.', 'Uma parte recorre de uma decisão sobre tutela provisória por meio de agravo de instrumento.', 'Art. 1.015', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('apelacao', 'Apelação', 'Processo civil', 'Recurso apresentado contra uma sentença para que o tribunal reexamine a decisão, conforme os limites do pedido feito pela parte.', 'Após uma sentença em uma ação de cobrança, uma das partes apresenta apelação para pedir sua revisão.', 'Arts. 1.009 e 1.010', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('arbitragem', 'Arbitragem', 'Formas de resolução de conflitos', 'Forma de resolver certos conflitos fora do julgamento comum pelo Poder Judiciário, por decisão de árbitro escolhido pelas partes. A lei permite seu uso para direitos patrimoniais disponíveis.', 'Duas empresas podem submeter uma divergência contratual à arbitragem quando a lei permitir.', 'Art. 3º, § 1º, do CPC e art. 1º da Lei nº 9.307/1996', 'arbitragem');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('audiencia-conciliacao', 'Audiência de conciliação ou mediação', 'Processo civil', 'Encontro previsto no processo para que as partes tentem chegar a um acordo com a ajuda de um conciliador ou mediador, quando cabível.', 'Em uma ação de cobrança, as partes participam de uma audiência para tentar combinar uma forma de pagamento.', 'Arts. 165 e 334', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('capacidade-processual', 'Capacidade processual', 'Processo civil', 'Aptidão para participar de um processo e praticar atos em nome próprio. Em algumas situações, a pessoa precisa ser representada ou assistida conforme a lei.', 'Uma pessoa maior e capaz pode participar do processo em nome próprio, com representação por advogado quando exigida.', 'Arts. 70 a 76', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('competencia', 'Competência', 'Processo civil', 'Conjunto de regras que indica qual órgão do Judiciário pode analisar determinado processo.', 'A lei e as características do caso ajudam a definir em qual foro a ação deve ser apresentada.', 'Arts. 42 a 66', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('conexao', 'Conexão', 'Processo civil', 'Relação entre processos que têm em comum o pedido ou a causa de pedir. A lei prevê a reunião de processos conexos em certas situações para evitar decisões incompatíveis.', 'Duas ações ligadas ao mesmo contrato podem ser analisadas em conjunto se os requisitos legais estiverem presentes.', 'Art. 55', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('cumprimento-de-sentenca', 'Cumprimento de sentença', 'Processo civil', 'Etapa em que se busca realizar na prática uma obrigação reconhecida em uma decisão judicial, seguindo o procedimento previsto para cada caso.', 'Depois de uma condenação definitiva ao pagamento, a parte vencedora pode pedir o cumprimento da sentença.', 'Arts. 513 e seguintes', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('embargos-de-declaracao', 'Embargos de declaração', 'Processo civil', 'Recurso usado para pedir que o órgão julgador esclareça obscuridade, elimine contradição, supra uma omissão ou corrija erro material em uma decisão.', 'A parte apresenta embargos de declaração porque a decisão não analisou um pedido feito no processo.', 'Arts. 1.022 e 1.023', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('embargos-a-execucao', 'Embargos à execução', 'Processo civil', 'Meio de defesa pelo qual a pessoa cobrada em uma execução pode apresentar ao Judiciário as questões previstas em lei.', 'O devedor apresenta embargos à execução para discutir, entre outros pontos permitidos, o valor cobrado.', 'Arts. 914 e 917', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('execucao', 'Execução', 'Processo civil', 'Procedimento destinado a buscar o cumprimento de uma obrigação que consta de um título executivo, conforme as regras legais aplicáveis.', 'Se uma obrigação documentada em título executivo não é cumprida, o credor pode pedir sua execução judicial.', 'Arts. 771 e seguintes', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('incidente-desconsideracao-personalidade-juridica', 'Incidente de desconsideração da personalidade jurídica', 'Processo civil', 'Procedimento que permite discutir, dentro do processo, se estão presentes os requisitos legais para estender determinados efeitos a sócios ou à pessoa jurídica.', 'Durante uma execução, uma parte pede a abertura do incidente e os envolvidos podem se manifestar antes da decisão.', 'Arts. 133 a 137', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('intervencao-de-terceiros', 'Intervenção de terceiros', 'Processo civil', 'Participação no processo de alguém que inicialmente não era parte, nas situações e formas autorizadas pela lei.', 'Uma pessoa com interesse jurídico no resultado pode pedir para atuar como assistente de uma das partes.', 'Arts. 119 a 138', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('litisconsorcio', 'Litisconsórcio', 'Processo civil', 'Participação de duas ou mais pessoas como autoras ou rés no mesmo processo, quando a lei permite ou quando há relação entre os pedidos ou direitos discutidos.', 'Duas pessoas que sofreram o mesmo dano podem, se os requisitos forem atendidos, apresentar uma ação juntas.', 'Arts. 113 a 118', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('litispendencia', 'Litispendência', 'Processo civil', 'Situação em que já existe um processo em andamento com as mesmas partes, o mesmo pedido e a mesma causa de pedir. A lei trata essa repetição como matéria que pode impedir o prosseguimento da nova ação.', 'Uma parte não pode simplesmente iniciar outra ação idêntica enquanto a primeira ainda está em andamento.', 'Art. 337, VI e §§ 1º a 3º', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('litigancia-de-ma-fe', 'Litigância de má-fé', 'Processo civil', 'Conduta processual que se enquadra nas hipóteses legais de deslealdade, como alterar intencionalmente a verdade dos fatos. Pode levar às consequências previstas no CPC.', 'A parte que altera de propósito um fato relevante pode estar sujeita às medidas previstas em lei.', 'Arts. 79 a 81', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('negocio-juridico-processual', 'Negócio jurídico processual', 'Processo civil', 'Acordo pelo qual as partes, nos limites previstos em lei, ajustam aspectos do procedimento ou de seus deveres processuais. O juiz pode controlar a validade do acordo.', 'Em uma causa sobre direito que admite acordo, as partes podem combinar um calendário para determinados atos do processo.', 'Art. 190', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('preclusao', 'Preclusão', 'Processo civil', 'Perda da possibilidade de praticar um ato ou discutir uma questão no processo, por motivo previsto em lei, como o fim do prazo ou a prática anterior do ato.', 'Se uma parte deixa passar o prazo para apresentar uma manifestação, pode perder a oportunidade de fazê-la naquele momento.', 'Arts. 223 e 507', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('producao-antecipada-da-prova', 'Produção antecipada da prova', 'Processo civil', 'Procedimento para produzir uma prova antes do momento habitual, nas situações previstas em lei, como quando ela pode se tornar impossível ou quando seu conhecimento pode ajudar a evitar uma ação.', 'Uma pessoa pede uma perícia antes do processo principal porque há risco de a situação examinada mudar.', 'Art. 381', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('reconvencao', 'Reconvenção', 'Processo civil', 'Pedido feito pelo réu contra o autor dentro do mesmo processo, junto à contestação, desde que exista relação com a ação ou com o fundamento da defesa.', 'Em uma ação de cobrança, o réu também pode apresentar um pedido relacionado ao mesmo contrato, se a lei permitir.', 'Art. 343', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('revelia', 'Revelia', 'Processo civil', 'Situação em que o réu não apresenta contestação. Isso pode gerar efeitos sobre os fatos alegados pelo autor, mas a própria lei prevê exceções.', 'Mesmo sem contestação, o juiz verifica se há alguma exceção legal antes de considerar verdadeiros os fatos alegados.', 'Arts. 344 e 345', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('saneamento-do-processo', 'Saneamento e organização do processo', 'Processo civil', 'Etapa em que o juiz resolve questões pendentes e organiza o que ainda precisa ser esclarecido, como os fatos discutidos e as provas a produzir.', 'Após as primeiras manifestações, o juiz define quais fatos ainda precisam de prova e quais provas serão produzidas.', 'Art. 357', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('tutela-de-evidencia', 'Tutela de evidência', 'Processo civil', 'Medida provisória que pode ser concedida quando a situação se enquadra nas hipóteses legais e as provas apresentadas justificam a proteção do direito, sem exigir demonstração de perigo de dano.', 'Uma parte pede uma medida com base em prova documental e em uma das hipóteses previstas no CPC.', 'Art. 311', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('tutela-cautelar', 'Tutela cautelar', 'Processo civil', 'Medida provisória de urgência voltada a proteger o resultado útil do processo, sem antecipar necessariamente o resultado final pedido pela parte.', 'Uma parte pede o bloqueio provisório de um bem para evitar que ele desapareça antes do fim do processo, se os requisitos legais forem atendidos.', 'Arts. 300 e 301', 'cpc');
INSERT INTO glossario_termos (id, termo, area, definicao, exemplo, referencia, fonte_id) VALUES ('tutela-antecipada', 'Tutela antecipada', 'Processo civil', 'Medida provisória de urgência que antecipa, total ou parcialmente, efeitos do que foi pedido no processo, quando os requisitos legais estão presentes.', 'Uma pessoa pede o restabelecimento provisório de um serviço enquanto a ação ainda está sendo julgada.', 'Arts. 300 e 303', 'cpc');
